exec(open('actions-lib.py').read())
wait()
DEMO=['Generic Saw','Generic Drill','Generic Attacher','Circular Saw','Table Saw','Band Saw','Chain Saw','Drill Press','CNC Router','Doweling Jig','Screw Gun']
EXT=['Chop Saw','Angle Grinder','Pillar Drill','Mag Drill','Plasma Cutter','MIG Welder','Stud Welder','Diamond Saw','Wall Saw','Wire Saw','Core Drill','Rotary Hammer','Anchor Setter','Surface Grinder','6-Axis Robotic Mill','5-Axis Gantry CNC','Waterjet','Laser Cutter','Robotic Assembler']
INSTALLED="window.__installed=()=>{const l=window.__h.labels();const hdr=['METAL','CONCRETE','ROBOTIC'].map(x=>l.indexOf(x)).filter(i=>i>=0);const end=hdr.length?Math.min(...hdr):l.length;return l.slice(0,end)};"
J=lambda v: json.dumps(v)
def ROW(label): return "(async()=>{const e=window.__h.find(%s);if(!e)throw new Error('no row %s');e.scrollIntoView({block:'center'});const r=e.getBoundingClientRect();return JSON.stringify([r.x+Math.min(40,r.width/2),r.y+r.height/2])})()"%(J(label),label)
def MENU(item): return "(async()=>{const e=await window.__h.until(()=>[...document.querySelectorAll('[role=menuitem]')].find(e=>e.innerText.trim().startsWith(%s)),8000,'menu item %s');const r=e.getBoundingClientRect();return JSON.stringify([r.x+r.width/2,r.y+r.height/2])})()"%(J(item),item)
step("P0 demo loaded","await h.actions();const s=await h.stepsNow(s=>s.n===4,150000,'demo steps');"+INSTALLED+"return h.json(s)",timeoutMs=170000)
step("P1 Workshop lists the demo's installed machines and the uninstalled metal, concrete and robotic sections","h.click('Workshop');await h.until(()=>h.find('Table Saw'),30000,'workshop rows');const inst=window.__installed();for(const m of %s)h.ok(inst.includes(m),'installed '+m+' in '+h.json(inst));for(const m of %s)h.ok(!inst.includes(m),'not yet installed '+m+' in '+h.json(inst));const l=h.labels();for(const g of ['METAL','CONCRETE','ROBOTIC'])h.ok(l.includes(g),'section '+g+' in '+h.json(l));return h.json(l)"%(J(DEMO),J(EXT)))
step("P2 expanding the sections lists all 19 machines of the metal, concrete and robotic extensions","for(const g of ['METAL','CONCRETE','ROBOTIC']){if(!h.find('Chop Saw')||!h.find('Diamond Saw')||!h.find('Waterjet')){const b=h.find(g);if(b)b.click();await h.wait(700)}}const l=h.labels();const miss=%s.filter(m=>!l.includes(m));h.ok(!miss.length,'missing machines '+h.json(miss)+' in '+h.json(l));return h.json(l)"%J(EXT))
step("P3 installing Waterjet, Chop Saw and Diamond Saw through their Workshop rows moves them into the installed list","const done=[];for(const [g,m] of [['ROBOTIC','Waterjet'],['METAL','Chop Saw'],['CONCRETE','Diamond Saw']]){if(!h.find(m)){h.find(g).click();await h.until(()=>h.find(m),15000,'expand '+g)}h.find(m).click();await h.until(()=>window.__installed().includes(m),30000,m+' installed');done.push(m)}const inst=window.__installed();for(const m of %s)h.ok(inst.includes(m),'demo machine kept '+m);return h.json([done,inst])"%J(DEMO),capture=True,minCanvasPixels=200)
step("P4 Catalogue lists the capabilities of the newly installed machines","h.click('Catalogue');await h.until(()=>h.find('Generic Saw — Cut'),30000,'catalogue rows');const want=['Chop Saw — Chop','Waterjet — Jet Cut','Diamond Saw — Crosscut','Generic Saw — Cut','Table Saw — Rip'];await h.until(()=>{const t=document.body.innerText;return want.every(w=>t.includes(w))},30000,'catalogue rows '+h.json(want));return h.json(h.labels().filter(x=>x.includes(' — ')).slice(0,60))")
step("P5 open Workshop for removal","h.click('Workshop');await h.until(()=>window.__installed().includes('Waterjet'),30000,'waterjet installed row');return h.json(window.__installed())")
step("P6 right-click the installed Waterjet row","return 'r'",pointer=ROW('Waterjet'),button=2,settleMs=1200)
step("P7 the context menu offers Remove","const items=[...document.querySelectorAll('[role=menuitem]')].map(e=>e.innerText.trim());h.ok(items.some(i=>i.startsWith('Remove')),'menu items '+h.json(items));return h.json(items)")
step("P8 click Remove in the context menu","return 'm'",pointer=MENU('Remove'),settleMs=1500)
step("P9 Waterjet is uninstalled while Chop Saw, Diamond Saw and the demo machines remain","const inst=await h.until(()=>{const i=window.__installed();return i.includes('Waterjet')?null:i},30000,'waterjet removed');for(const m of ['Chop Saw','Diamond Saw',...%s])h.ok(inst.includes(m),'kept '+m+' in '+h.json(inst));h.ok(h.labels().includes('Waterjet'),'Waterjet returns to the uninstalled robotic section');return h.json(inst)"%J(DEMO),capture=True,minCanvasPixels=200)
step("P10 Catalogue drops the Waterjet capability and keeps the other installed machines","h.click('Catalogue');await h.until(()=>h.find('Generic Saw — Cut'),30000,'catalogue');await h.until(()=>!document.body.innerText.includes('Waterjet — '),30000,'waterjet capability gone');const t=document.body.innerText;for(const w of ['Chop Saw — Chop','Diamond Saw — Crosscut','Generic Saw — Cut','Table Saw — Rip'])h.ok(t.includes(w),'catalogue keeps '+w);return 'ok'")
step("P11 the document is unchanged apart from the workshop","const s=h.steps();h.ok(s&&s.n===4&&Math.abs(s.vol-0.174)<1e-3,'steps '+h.json(s));return h.json(s)")
save("process-actions-panels.json")
